with base as (select id, customer_id, start_date, end_date, monthly_fee, status, concat(status, '/', plan) as status_plan, length(status) as status_length from subscriptions where start_date > to_date('2023-10-02')) select s.*, sub.id as subscription_id, sub.plan, sub.monthly_fee as subscription_monthly_fee from base s inner join subscriptions sub on s.customer_id = sub.customer_id and s.end_date between sub.start_date and sub.end_date
